import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";

// Each command is defined once and rendered two ways:
// - as an MCP prompt, which clients show as /mcp__local-llm__<name> (Claude Code) or
//   /mcp.local-llm.<name> (VS Code), with typed arguments filled in by the client;
// - as a Claude Code command file, /local_<name>, generated by scripts/commands.mjs, where the
//   arguments arrive as one raw $ARGUMENTS string the calling model has to read.
// Either way the text instructs the *calling* model. The local model never sees it; it only sees
// what the calling model decides to send, which is why every command ends with a verification step.

const GROUND_RULES =
  "Ground rules:\n" +
  "- Use the local-llm tools for the generation step; do the reading, trimming and checking yourself. " +
  "The local model has no file access, no repo context and no memory between calls, so every call " +
  "must carry all the text it needs.\n" +
  "- Keep maxTokens tight: locally it runs at roughly 16 tokens per second.\n" +
  "- Stay on the default provider unless the user asked for OpenRouter. Never send secrets, keys or " +
  "private data to provider=\"openrouter\".\n" +
  "- If a call fails because Ollama is unreachable, say so and stop; do not silently do the work " +
  "yourself instead.\n" +
  "- Treat the reply as a draft. Check it against the source before presenting it, fix what is wrong, " +
  "and say briefly what you changed.";

const SOURCE_FORMS =
  "If the source is a file path, read the file. If it is a shell command, run it and use its output. " +
  "Otherwise treat it as the text itself.";

// Text the user may point at: a path, a command to run, or nothing.
function sourceOf(target: string | undefined, fallback: string): string {
  const t = target?.trim();
  return t ? `The source is: ${t}\n${SOURCE_FORMS}` : fallback;
}

type Args = Record<string, string | undefined>;

export interface Command {
  name: string;
  title: string;
  description: string;
  argumentHint: string;
  argsSchema: Record<string, z.ZodType<string> | z.ZodOptional<z.ZodType<string>>>;
  /** Tools the generated command file pre-approves. */
  allowedTools: string[];
  /** Opening for the MCP prompt, with the client's typed arguments filled in. */
  header: (args: Args) => string;
  /** Opening for the command file: how to read the raw $ARGUMENTS string. */
  rawHeader: string;
  body: string;
}

const ASK_TOOLS = ["mcp__local-llm__local_ask", "Read"];

export const COMMANDS: Command[] = [
  {
    name: "ask",
    title: "Ask the local model",
    description: "Send a question or instruction to the local model and show its answer.",
    argumentHint: "<question>",
    argsSchema: { question: z.string().describe("What to ask.") },
    allowedTools: ASK_TOOLS,
    header: ({ question }) => `Request: ${question?.trim() ?? ""}`,
    rawHeader: "Request: $ARGUMENTS\n\nIf the request is empty, ask the user what to send.",
    body:
      "Answer the request with local_ask. If it refers to a file or command output, read it yourself " +
      "and include the relevant part in the prompt. Pick maxTokens to fit the expected answer length " +
      "(160 is about 10 seconds). Present the answer with the model name and time taken.",
  },
  {
    name: "summarize",
    title: "Summarise with the local model",
    description: "Summarise a file, command output, or the last long output in the conversation.",
    argumentHint: "[file | command | text] [focus]",
    argsSchema: {
      target: z.string().optional().describe("File path or command. Omit for the last output."),
      focus: z.string().optional().describe("What the summary should concentrate on."),
    },
    allowedTools: ASK_TOOLS,
    header: ({ target, focus }) =>
      sourceOf(target, "The source is the most recent long tool output or text in this conversation.") +
      (focus?.trim() ? `\nFocus on: ${focus.trim()}` : ""),
    rawHeader:
      "Arguments: $ARGUMENTS\n\n" +
      "The arguments name the source and may add what to focus on. " +
      SOURCE_FORMS +
      " If there are no arguments, the source is the most recent long tool output or text in this " +
      "conversation.",
    body:
      "Summarise the source with local_ask. Send it with a system prompt asking for a short plain " +
      "summary: what happened, anything that failed, and anything needing action. Use maxTokens around " +
      "200. If the text is very long, drop repetitive lines (progress bars, repeated warnings) before " +
      "sending rather than cutting off the end, where errors usually are. Then check every claim in the " +
      "summary against the source; a summary that invents an error or misses one is worse than none.",
  },
  {
    name: "commit",
    title: "Draft a commit message locally",
    description: "Draft a commit message for the staged diff with the local model, then check it.",
    argumentHint: "[what the message should mention]",
    argsSchema: { hint: z.string().optional().describe("Anything the message should mention.") },
    allowedTools: [...ASK_TOOLS, "Bash(git diff:*)", "Bash(git log:*)", "Bash(git status:*)"],
    header: ({ hint }) => (hint?.trim() ? `Context from the user: ${hint.trim()}` : "No extra context from the user."),
    rawHeader: "Context from the user (may be empty): $ARGUMENTS",
    body:
      "Draft a commit message with local_ask.\n\n" +
      "1. Run `git diff --staged`. If nothing is staged, run `git diff` and say the message covers " +
      "unstaged changes. If there are no changes at all, stop and say so.\n" +
      "2. Run `git log --oneline -10` to see the repository's subject style.\n" +
      "3. Send the diff to local_ask. Leave out lockfiles, binaries and generated output, and trim very " +
      "large hunks to their headers. System prompt: write a commit message in the style of the example " +
      "subjects (include them), an imperative subject under 72 characters, then a blank line and a short " +
      "body explaining why. Output only the message. Use maxTokens around 150.\n" +
      "4. Check the draft against the diff: every claim must be true of the change, and nothing important " +
      "may be missing. Correct it.\n" +
      "5. Show the final message. Do not commit unless the user asked you to.",
  },
  {
    name: "triage",
    title: "Triage items into labels",
    description: "Classify each item (log lines, errors, files) into your labels with local_classify.",
    argumentHint: "<label,label,...> [file | command | text]",
    argsSchema: {
      labels: z.string().describe("Comma-separated labels, e.g. bug,config,noise"),
      target: z.string().optional().describe("File path or command. Omit for the last list."),
    },
    allowedTools: ["mcp__local-llm__local_classify", "Read"],
    header: ({ labels, target }) => {
      const set = (labels ?? "")
        .split(",")
        .map((l) => l.trim())
        .filter(Boolean);
      return (
        `Labels: ${JSON.stringify(set)}\n` +
        (set.length < 2 ? "Fewer than two labels were given; ask the user for the label set before calling.\n" : "") +
        sourceOf(target, "The source is the most recent list of items in this conversation (log lines, files, errors).")
      );
    },
    rawHeader:
      "Arguments: $ARGUMENTS\n\n" +
      "The first argument is the comma-separated label set; anything after it is the source. " +
      SOURCE_FORMS +
      " With no source, use the most recent list of items in this conversation (log lines, files, " +
      "errors). If fewer than two labels are given, ask the user for the label set before calling.",
    body:
      "Split the source into items — one per line or entry — and call local_classify once per item with " +
      "the labels. Independent calls can run in parallel. Report a table of item and label, then list " +
      "separately the items that came back declined=true (none of the labels fit) and matched=false " +
      "(unclassified). Do not assign those yourself without saying so. A returned label is triage, not a " +
      "verdict: spot-check a few, and flag any you disagree with.",
  },
  {
    name: "extract",
    title: "Extract fields as JSON",
    description: "Pull named fields out of text as JSON, then check each value is really there.",
    argumentHint: "<field,field,...> [file | command | text]",
    argsSchema: {
      fields: z.string().describe("Comma-separated field names, e.g. version,date,author"),
      target: z.string().optional().describe("File path or command. Omit for the last text."),
    },
    allowedTools: ASK_TOOLS,
    header: ({ fields, target }) =>
      `Fields: ${fields?.trim() ?? ""}\n` +
      sourceOf(target, "The source is the most recent relevant text in this conversation."),
    rawHeader:
      "Arguments: $ARGUMENTS\n\n" +
      "The first argument is the comma-separated field names; anything after it is the source. " +
      SOURCE_FORMS +
      " With no source, use the most recent relevant text in this conversation.",
    body:
      "Extract the fields with local_ask. Ask for a single JSON object with exactly those keys, null for " +
      "any field not present, and no other text. Use temperature 0 and a maxTokens that fits the fields. " +
      "Parse the reply; if it is not valid JSON, retry once with the parse error in the prompt. Then " +
      "confirm each non-null value actually appears in the source. Set any that do not to null and say " +
      "which.",
  },
];

function compose(header: string, body: string): string {
  return `${header}\n\n${body}\n\n${GROUND_RULES}`;
}

/** Text of the MCP prompt for these arguments. */
export function renderPrompt(cmd: Command, args: Args): string {
  return compose(cmd.header(args), cmd.body);
}

/** A Claude Code command file (/local_<name>) for this command. */
export function renderCommandFile(cmd: Command): string {
  return (
    "---\n" +
    `description: ${cmd.description}\n` +
    `argument-hint: ${cmd.argumentHint}\n` +
    `allowed-tools: ${cmd.allowedTools.join(", ")}\n` +
    "---\n\n" +
    "<!-- Generated from src/prompts.ts by `npm run commands`. Edit there, not here. -->\n\n" +
    compose(cmd.rawHeader, cmd.body) +
    "\n"
  );
}

export function registerPrompts(server: McpServer): void {
  for (const cmd of COMMANDS) {
    server.registerPrompt(
      cmd.name,
      { title: cmd.title, description: cmd.description, argsSchema: cmd.argsSchema },
      (args: Args) => ({
        messages: [{ role: "user" as const, content: { type: "text" as const, text: renderPrompt(cmd, args) } }],
      }),
    );
  }
}
